lemma intervalIntegrable_sub_edgeMax_sq (hK : IsCompact K) (hne : K.Nonempty) {f : ℝ → ℝ}
    {a b : ℝ} (hf : ContinuousOn f (uIcc a b)) :
    IntervalIntegrable (fun s => (f s - edgeMax K s) ^ 2) volume a b
